// @vitest-environment node
import 'fake-indexeddb/auto'
import { readFile, writeFile } from 'node:fs/promises'
import { afterAll, expect, it } from 'vitest'
import { db } from '../../src/db/database'
import { prepareBackup, readBackup, restoreBackup } from '../../src/db/backup'

// Generated by Android v1.12.0's IronLogExporter, using the synthetic data from
// IronLogBackupRoundTripTest plus preferredWeightUnit = "kg". All loads stay in lb.
const fixtureUrl = new URL('./android-v2.zip', import.meta.url)
afterAll(() => db.delete())

it('restores the Android exporter ZIP and re-exports all eight linked tables and preferences', async () => {
  const android = await readBackup(new Uint8Array(await readFile(fixtureUrl)))
  expect(android.source).toBe('android')
  expect(android.version).toBe(2)
  expect(android.counts).toEqual({
    muscleGroups: 3, exercises: 2, routines: 1, routineDays: 1, routineExercises: 1,
    workouts: 1, sets: 2, workoutExerciseInstances: 1,
  })
  await restoreBackup(android, 'replace')
  const [workout] = await db.workouts.toArray()
  const [plan] = await db.workout_exercise_instances.toArray()
  const [lift, cardio] = await db.exercises.orderBy('id').toArray()
  const [firstSet, secondSet] = await db.sets.orderBy('timestamp').toArray()
  const [day] = await db.routine_days.toArray()
  const [plannedLift] = await db.routine_exercises.toArray()

  expect(workout).toMatchObject({
    name: 'Pull, Heavy', note: 'Felt strong\nSecond line\r\nThird "quoted" line',
    rating: 5, ratingNote: 'PR day\rKeep volume', routineId: day.routineId, routineDayId: day.id,
    routineNameSnapshot: 'PPL', routineDayNameSnapshot: 'Pull Day', startedFromRoutine: true,
  })
  expect(lift).toMatchObject({ name: 'Row, "Barbell"', notes: 'Line 1\nLine 2\r\nLine "3"', isStarred: true, repTarget: 8 })
  expect(firstSet).toMatchObject({ workoutId: workout.id, exerciseId: lift.id, weight: 185, reps: 8, rpe: 8.5, note: 'Strict form,\nno straps' })
  expect(secondSet).toMatchObject({ exerciseId: cardio.id, weight: null, distanceValue: 5, distanceUnit: 'KILOMETERS', distanceMeters: 5000, calories: 320 })
  expect(plan).toMatchObject({ workoutId: workout.id, exerciseId: lift.id, routineExerciseId: plannedLift.id, notes: 'Instance note\nline 2', addedDuringWorkout: true })
  expect(await db.preferences.get('default')).toMatchObject({
    preferredWeightUnit: 'kg', barWeight: 35, plateInventory: {'45': 4, '25': 2, '10': 6},
    bestStreak: 19, userName: 'Jamie', customThemeColor: '#FF6B35', themeFont: 'oswald',
  })

  const file = await prepareBackup()
  const bytes = new Uint8Array(await file.arrayBuffer())
  const pwa = await readBackup(bytes)
  expect(pwa.source).toBe('pwa')
  expect(pwa.counts).toEqual(android.counts)
  expect(pwa.data).toEqual(android.data)
  expect(pwa.preferences).toEqual(android.preferences)

  // Optional bridge to the Kotlin importer's JVM assertions in a separate checkout.
  if (process.env.IRONLOG_INTEROP_EXPORT) await writeFile(process.env.IRONLOG_INTEROP_EXPORT, bytes)

  await restoreBackup(android, 'merge')
  const merged = await readBackup(new Uint8Array(await (await prepareBackup()).arrayBuffer()))
  expect(merged.counts).toEqual(android.counts)
})
